\label{thm:main}
Under \eqref{eq:assumptions},
\begin{equation}
\lambda_1^D(M)\ge\max\{nK,B_\eta\}.
\label{eq:main-bound}
\end{equation}
For $0<s<1$ one has the strict model estimate
\begin{equation}
B_\eta<\mu<\lambda_1^D(M).
\label{eq:strict-model}
\end{equation}
At $s=1$, the weighted Kasue model has first eigenvalue
$\mu=nK$ and $B_\eta<nK$.

\label{cor:asymptotics}
For fixed $n$, as $s\downarrow0$,
\begin{equation}
\frac{X}{\Lambda_R}
=1+cs+\beta a_0s^2+\beta a_1s^3+O_n(s^4),
\qquad X\in\{\mu,B_\eta\}.
\label{eq:main-expansion}
\end{equation}
Consequently,
\begin{equation}
\mu-B_\eta=O_n(\Lambda_Rs^4),\qquad
\frac{\mu-B_\eta}{\mu}=O_n(s^4).
\label{eq:error}
\end{equation}

\label{lem:reduction}
Let $\lambda_\beta^{ND}$ be the first eigenvalue of
\[
H_\beta=-\frac{d^2}{dr^2}+\beta W
\]
on $[0,R]$ with Neumann condition at $0$ and Dirichlet condition at
$R$. Then
\begin{equation}
\mu=\alpha+\lambda_\beta^{ND},
\qquad
\mu\le L+\beta KJ(s).
\label{eq:reduction}
\end{equation}

\label{thm:moment-optimality}
Let $0<m_1<1$ and $m_1^2<m_2<m_1$. Let $\mathcal P(m_1,m_2)$ be
the set of probability measures on $[0,1]$ with first and second
moments $m_1$ and $m_2$. Then
\begin{equation}
\min_{\nu\in\mathcal P(m_1,m_2)}J_\nu(s)
=\frac{m_1s}{1-(m_2/m_1)s}
\qquad(0<s\le1).
\label{eq:moment-envelope}
\end{equation}
For each $s$, the unique minimizing measure is
\begin{equation}
\nu_*=
\left(1-\frac{m_1^2}{m_2}\right)\delta_0
+\frac{m_1^2}{m_2}\delta_{m_2/m_1},
\label{eq:extremal-law}
\end{equation}
where $\delta_x$ is the Dirac measure at $x$.

\label{lem:moments}
There is a probability measure $\nu_0$ on $[0,1]$ with
$\nu_0((0,1))=1$ and nonconstant coordinate variable $Y$ such that
\begin{equation}
J(s)=J_{\nu_0}(s),\qquad
\mathbb E Y=a_0,\quad \mathbb E Y^2=a_1,
\qquad 0<s\le1.
\label{eq:model-moments}
\end{equation}
In particular, $0<a_0<1$ and $a_0^2<a_1<a_0$. Moreover,
$J(1)=1$ and
\begin{equation}
J(s)=a_0s+a_1s^2+O(s^3)
\qquad(s\downarrow0).
\label{eq:Jexp}
\end{equation}

\label{lem:moment-minorant}
One has $0<\eta<1$, $J(1)=1$, and
\begin{equation}
J(s)>j_\eta(s)=\frac{a_0s}{1-\eta s}>0,
\qquad 0<s\le1.
\label{eq:moment-minorant}
\end{equation}

\label{lem:corrector}
For $0<s<1$, define on $[0,R)$
\begin{equation}
f(r)=\psi_0(r)^{-2}
\int_0^r(\overline W-W(t))\psi_0(t)^2\,dt.
\label{eq:f}
\end{equation}
Then $f$ extends smoothly to $[0,R]$, vanishes at both endpoints, and
satisfies the sharp estimates
\begin{align}
0<f(r)&<\frac{\overline W}{k}\tan(kr)
\qquad(0<r<R),\label{eq:f-bound}\\
\sup_{0<r<R}\frac{f(r)^2}{W(r)}&=J(s)^2.
\label{eq:sharp-corrector}
\end{align}

\label{lem:endpoint}
At $s=1$, the weighted Kasue model has first eigenvalue $nK$.
Moreover $B_\eta<nK$.

\label{cor:moment-transfer}
For $n\ge2$, $K>0$, and $0<s\le1$,
\begin{equation}
\min_{\nu\in\mathcal P(a_0,a_1)}
\bigl[L+\Phi(J_\nu(s))\bigr]
=L+\Phi(j_\eta(s))=B_\eta.
\label{eq:moment-transfer}
\end{equation}
Consequently, if a positive function $\underline J(s)$ satisfies
$\underline J(s)\le J_\nu(s)$ for every
$\nu\in\mathcal P(a_0,a_1)$, then
$L+\Phi(\underline J(s))\le B_\eta$.

\label{cor:variance-comparison}
For every $n\ge2$ and $0<s\le1$,
\begin{equation}
B_\eta>B_{\mathrm{var}}.
\label{eq:variance-dominance}
\end{equation}

\label{prop:power}
Under \eqref{eq:assumptions},
\begin{equation}
\lambda_1^D(M)\ge B_{\mathrm{pow}},
\label{eq:power-bound}
\end{equation}
where
\begin{equation}
B_{\mathrm{pow}}=
\begin{cases}
L+\alpha^2/(4\Lambda_R),&\alpha\le2\Lambda_R,\\
2\alpha,&\alpha\ge2\Lambda_R.
\end{cases}
\label{eq:Bpow}
\end{equation}

\label{thm:crossover}
Let $u=cs$. For $0<u\le2$, define
\begin{equation}
D_c(u)=1-\frac1{4a_0}-\frac{u^2}{16}
+\frac{1}{c}+\frac{\eta u}{4a_0c}.
\label{eq:Dcu}
\end{equation}
Then
\begin{equation}
B_\eta\gtrless B_{\mathrm{pow}}
\quad\Longleftrightarrow\quad
D_c(u)\gtrless0.
\label{eq:exact-crossover}
\end{equation}
Equality holds if and only if $D_c(u)=0$. In the same range,
\begin{equation}
\frac{B_{\mathrm{pow}}-nK}{\Lambda_R}
=\left(1-\frac u2\right)^2-\frac uc.
\label{eq:power-reilly-comparison}
\end{equation}
If $u\ge2$, then $B_{\mathrm{pow}}=(n-1)K<nK$.
